cd plugin && ./gradlew --no-daemon test --tests PluginConfigTest --tests StaticFilesTest
```

Expected: 4 of the new/related tests fail because `runtimeReference` doesn't exist yet.

- [ ] **Step 4: Add `runtimeReference` to `PluginConfig`**

Replace the data-class declaration in `plugin/src/main/kotlin/com/juspay/smithy/mock/config/PluginConfig.kt` so it reads:

```kotlin
package com.juspay.smithy.mock.config

import software.amazon.smithy.model.node.ObjectNode

data class PluginConfig(
    val service: String?,
    val packageName: String,
    val packageVersion: String,
    val validateConfig: List<String>,
    val runtimeReference: String = "^0.0.0",
) {
    companion object {
        fun from(node: ObjectNode): PluginConfig {
            val packageName = node.getStringMember("packageName")
                .orElseThrow { IllegalArgumentException("plugin config: 'packageName' is required") }
                .value
            val packageVersion = node.getStringMember("packageVersion")
                .orElseThrow { IllegalArgumentException("plugin config: 'packageVersion' is required") }
                .value
            val service = node.getStringMember("service").map { it.value }.orElse(null)
            val validateConfig = node.getArrayMember("validateConfig")
                .map { arr -> arr.elements.map { it.expectStringNode().value } }
                .orElse(emptyList())
            val runtimeReference = node.getStringMember("runtimeReference")
                .map { it.value }
                .orElse("^0.0.0")

            return PluginConfig(
                service = service,
                packageName = packageName,
                packageVersion = packageVersion,
                validateConfig = validateConfig,
                runtimeReference = runtimeReference,
            )
        }
    }
}
```

- [ ] **Step 5: Wire `PackageJsonWriter` to emit the configured reference**

Replace `plugin/src/main/kotlin/com/juspay/smithy/mock/emit/PackageJsonWriter.kt` with:

```kotlin
package com.juspay.smithy.mock.emit

import com.juspay.smithy.mock.config.PluginConfig

class PackageJsonWriter {
    fun render(cfg: PluginConfig): String = """
        {
          "name": "${cfg.packageName}",
          "version": "${cfg.packageVersion}",
          "description": "Generated mock server",
          "main": "dist/index.js",
          "types": "dist/index.d.ts",
          "scripts": {
            "build": "tsc",
            "start": "node dist/index.js"
          },
          "dependencies": {
            "@smithy-mock-generator/runtime": "${cfg.runtimeReference}",
            "fastify": "^4.28.0"
          },
          "devDependencies": {
            "typescript": "^5.5.0",
            "@types/node": "^20.14.0"
          },
          "engines": {
            "node": ">=20"
          }
        }
    """.trimIndent() + "\n"
}
```

