git commit -m "feat(plugin): optional runtimeReference config overrides generated runtime dep" \
  -m "Adds a runtimeReference field to PluginConfig (default '^0.0.0'). Plumbs through PackageJsonWriter so the example can swap in a file: tarball reference at generation time, avoiding post-hoc package.json edits. Default behavior unchanged: the user-crud golden still emits ^0.0.0." \
  -m "Co-Authored-By: Claude Opus 4.7 <noreply@anthropic.com>"
