$version: "2.0"

namespace example

service Svc {
    version: "2026-05-08",
    resources: [User],
}

resource User {
    identifiers: { userId: String },
    create: CreateUser,
    read: GetUser,
    update: UpdateUser,
    delete: DeleteUser,
    list: ListUsers,
}

@http(method: "POST", uri: "/users", code: 200)
operation CreateUser {
    input := {
        @required @length(min: 1, max: 50)
        name: String,

        @range(min: 0, max: 150)
        age: Integer,

        status: UserStatus,
    },
    output := { user: UserData }
    errors: [Conflict]
}

@readonly
@http(method: "GET", uri: "/users/{userId}", code: 200)
operation GetUser {
    input := {
        @required @httpLabel @resourceIdentifier("userId")
        userId: String,
    },
    output := { user: UserData }
    errors: [NotFound]
}

@http(method: "PATCH", uri: "/users/{userId}", code: 200)
operation UpdateUser {
    input := {
        @required @httpLabel @resourceIdentifier("userId")
        userId: String,
        name: String,
        age: Integer,
        status: UserStatus,
    },
    output := { user: UserData }
    errors: [NotFound]
}

@idempotent
@http(method: "DELETE", uri: "/users/{userId}", code: 204)
operation DeleteUser {
    input := {
        @required @httpLabel @resourceIdentifier("userId")
        userId: String,
    },
    output := {}
    errors: [NotFound]
}

@readonly
@paginated(inputToken: "nextToken", outputToken: "nextToken", pageSize: "maxResults", items: "users")
@http(method: "GET", uri: "/users", code: 200)
operation ListUsers {
    input := {
        @httpQuery("maxResults") maxResults: Integer,
        @httpQuery("nextToken") nextToken: String,
    },
    output := {
        users: UserList,
        nextToken: String,
    }
}

structure UserData {
    @required userId: String,
    @required @length(min: 1, max: 50) name: String,
    @range(min: 0, max: 150) age: Integer,
    status: UserStatus,
}

list UserList { member: UserData }

enum UserStatus { ACTIVE, INACTIVE }

@error("client")
@httpError(404)
structure NotFound { @required message: String }

@error("client")
@httpError(409)
structure Conflict { @required message: String }
```

