## Task 5: e2e tests — CRUD round-trip

**Files:**
- Modify: `examples/user-mock/e2e/test-server.mjs`

Replace the stub with a real CRUD round-trip. The orchestration script (Task 7) sets `E2E_BASE_URL` to the running server's address before invoking `node --test`.

- [ ] **Step 1: Replace `examples/user-mock/e2e/test-server.mjs`**

```js
import { test } from 'node:test';
import assert from 'node:assert/strict';

const baseUrl = process.env.E2E_BASE_URL;
if (!baseUrl) throw new Error('E2E_BASE_URL not set; run via run-e2e.sh');

async function postJson(path, body) {
  const res = await fetch(`${baseUrl}${path}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: res.status !== 204 ? await res.json() : null };
}

async function getJson(path, init = {}) {
  const res = await fetch(`${baseUrl}${path}`, init);
  return { status: res.status, body: res.status !== 204 ? await res.json() : null };
}

test('CRUD round-trip on User resource', async () => {
  const create = await postJson('/users', { name: 'Alice', age: 30, status: 'ACTIVE' });
  assert.equal(create.status, 200, `expected 200, got ${create.status}`);
  const userId = create.body.user.userId;
  assert.ok(userId, 'created user has a userId');

  const got = await getJson(`/users/${userId}`);
  assert.equal(got.status, 200);
  assert.equal(got.body.user.name, 'Alice');

  const patch = await fetch(`${baseUrl}/users/${userId}`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ age: 31 }),
  });
  assert.equal(patch.status, 200);

  const list = await getJson('/users');
  assert.equal(list.status, 200);
  assert.equal(list.body.users.length, 1);

  const del = await fetch(`${baseUrl}/users/${userId}`, { method: 'DELETE' });
  assert.ok([200, 204].includes(del.status));

  const after = await getJson(`/users/${userId}`);
  assert.equal(after.status, 404);
  assert.match(after.body.message ?? '', /not found/i);
});

test('validation error returns 400 with field list', async () => {
  const res = await postJson('/users', {});  // missing required name
  assert.equal(res.status, 400);
  assert.equal(res.body.code, 'ValidationException');
  assert.ok(res.body.fieldList.some(f => f.path === 'name'));
});
```

