- [ ] **Step 2: Append scenario + admin tests to `examples/user-mock/e2e/test-server.mjs`**

Append below the existing tests (before the EOF):

```js
const adminUrl = process.env.E2E_ADMIN_URL;

test('admin: install scenario, then X-Mock-Scenario header drives behavior', async (t) => {
  if (!adminUrl) {
    t.skip('admin port not provided; skipping admin scenario test');
    return;
  }

  // Install a scenario via the admin override API so the test does not depend
  // on whether the generated server is reading a yaml config.
  const installFlaky = await fetch(`${adminUrl}/admin/operations/example%23GetUser/override?scenario=flaky`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      failureRate: 1.0,
      onFailure: { status: 503, body: { code: 'Unavailable' } },
    }),
  });
  assert.equal(installFlaky.status, 204, 'install flaky override');

  const installNotFound = await fetch(`${adminUrl}/admin/operations/example%23GetUser/override?scenario=user-not-found`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ error: 'example#NotFound' }),
  });
  assert.equal(installNotFound.status, 204, 'install user-not-found override');

  // Seed a user for the tests below.
  const create = await fetch(`${baseUrl}/users`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name: 'Bob', age: 22, status: 'ACTIVE' }),
  });
  assert.equal(create.status, 200);
  const seeded = await create.json();
  const userId = seeded.user.userId;

  // Default flow returns 200.
  const baseline = await fetch(`${baseUrl}/users/${userId}`);
  assert.equal(baseline.status, 200);

  // Flaky scenario forces 503.
  const flaky = await fetch(`${baseUrl}/users/${userId}`, {
    headers: { 'x-mock-scenario': 'flaky' },
  });
  assert.equal(flaky.status, 503);
  const flakyBody = await flaky.json();
  assert.equal(flakyBody.code, 'Unavailable');

  // user-not-found scenario routes through the modeled NotFound error.
  const missing = await fetch(`${baseUrl}/users/${userId}`, {
    headers: { 'x-mock-scenario': 'user-not-found' },
  });
  assert.equal(missing.status, 404);
  assert.equal(missing.headers.get('x-amzn-errortype'), 'NotFound');
});
```

