#!/usr/bin/env bash
# End-to-end pipeline:
# 1) pack runtime → 2) smithy build → 3) drop tarball next to generated package.json
# 4) install + build generated → 5) start server in background → 6) run node:test → 7) tear down

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
EXAMPLE_DIR="$REPO_ROOT/examples/user-mock"
GEN_DIR="$EXAMPLE_DIR/build/smithyprojections/user-mock-example/source/mock-server"
E2E_DIR="$EXAMPLE_DIR/e2e"
RUNTIME_DIR="$REPO_ROOT/runtime"

echo "=== 1. Pack runtime ==="
cd "$RUNTIME_DIR"
npm install --silent
npm run build --silent
RUNTIME_TGZ="$(npm pack --silent)"
test -f "$RUNTIME_DIR/$RUNTIME_TGZ"

echo "=== 2. Generate via smithy build (composite picks up :plugin) ==="
cd "$EXAMPLE_DIR"
./gradlew --no-daemon -q smithyBuild
test -f "$GEN_DIR/package.json"
test -f "$GEN_DIR/src/index.ts"

echo "=== 3. Drop runtime.tgz next to the generated package.json ==="
cp "$RUNTIME_DIR/$RUNTIME_TGZ" "$GEN_DIR/runtime.tgz"

echo "=== 4. Install + build generated package ==="
cd "$GEN_DIR"
npm install --silent
npm run build --silent
test -f "$GEN_DIR/dist/index.js"

echo "=== 5. Start server in background ==="
cd "$E2E_DIR"
rm -f address.json
node start-server.mjs &
SERVER_PID=$!
trap "kill $SERVER_PID 2>/dev/null || true; wait $SERVER_PID 2>/dev/null || true" EXIT

# Wait up to 10s for address.json to appear.
for i in $(seq 1 100); do
  if [ -f "$E2E_DIR/address.json" ]; then break; fi
  sleep 0.1
done
test -f "$E2E_DIR/address.json"

BASE_URL="$(node -e "console.log(JSON.parse(require('fs').readFileSync('address.json','utf8')).baseUrl)")"
ADMIN_URL="$(node -e "const a=JSON.parse(require('fs').readFileSync('address.json','utf8')).adminUrl; console.log(a||'')")"

echo "=== 6. Run e2e tests ==="
echo "    base=$BASE_URL"
echo "    admin=$ADMIN_URL"
E2E_BASE_URL="$BASE_URL" E2E_ADMIN_URL="$ADMIN_URL" node --test test-server.mjs

echo "=== 7. Done ==="
```

