import { checkAuth } from '../../src/middleware/auth';
import type { AuthRequirement } from '../../src/descriptors/operation';

const bearerOnly: AuthRequirement = { schemes: ['smithy.api#httpBearerAuth'], optional: false };

describe('checkAuth', () => {
  it('passes when scheme is configured ignore', () => {
    const r = checkAuth(bearerOnly, { 'smithy.api#httpBearerAuth': { mode: 'ignore' } }, {});
    expect(r.ok).toBe(true);
  });

  it('passes when presence and Authorization header present', () => {
    const r = checkAuth(bearerOnly, { 'smithy.api#httpBearerAuth': { mode: 'presence' } }, { authorization: 'Bearer xyz' });
    expect(r.ok).toBe(true);
  });

  it('fails when presence and Authorization missing', () => {
    const r = checkAuth(bearerOnly, { 'smithy.api#httpBearerAuth': { mode: 'presence' } }, {});
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.envelope.statusCode).toBe(401);
  });

  it('passes when value-match accepts the bearer token', () => {
    const r = checkAuth(
      bearerOnly,
      { 'smithy.api#httpBearerAuth': { mode: 'value-match', accept: ['secret'] } },
      { authorization: 'Bearer secret' },
    );
    expect(r.ok).toBe(true);
  });

  it('fails when value-match rejects the bearer token', () => {
    const r = checkAuth(
      bearerOnly,
      { 'smithy.api#httpBearerAuth': { mode: 'value-match', accept: ['secret'] } },
      { authorization: 'Bearer wrong' },
    );
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.envelope.statusCode).toBe(401);
  });

  it('passes when no auth requirement', () => {
    const r = checkAuth(undefined, {}, {});
    expect(r.ok).toBe(true);
  });
});

