class AuthResolverTest {
    private fun model(src: String): Model = Model.assembler()
        .discoverModels(this::class.java.classLoader)
        .addUnparsedModel("t.smithy", src)
        .assemble()
        .unwrap()

    @Test
    fun `service-level auth applies to operations without override`() {
        val m = model("""
            ${"$"}version: "2.0"
            namespace example
            @httpBearerAuth
            @auth([httpBearerAuth])
            service Svc { operations: [Op] }
            operation Op { input := {}, output := {} }
        """.trimIndent())

        val svc = m.expectShape(ShapeId.from("example#Svc")).asServiceShape().get()
        val op = m.expectShape(ShapeId.from("example#Op")).asOperationShape().get()

        val req = AuthResolver.resolve(m, svc, op)
        assertThat(req?.schemes).containsExactly("smithy.api#httpBearerAuth")
        assertThat(req?.optional).isFalse()
    }

    @Test
    fun `operation-level @auth overrides service-level`() {
        val m = model("""
            ${"$"}version: "2.0"
            namespace example
            @httpBearerAuth
            @httpApiKeyAuth(name: "x-api-key", in: "header")
            @auth([httpBearerAuth])
            service Svc { operations: [Op] }
            @auth([httpApiKeyAuth])
            operation Op { input := {}, output := {} }
        """.trimIndent())

        val svc = m.expectShape(ShapeId.from("example#Svc")).asServiceShape().get()
        val op = m.expectShape(ShapeId.from("example#Op")).asOperationShape().get()

        val req = AuthResolver.resolve(m, svc, op)
        assertThat(req?.schemes).containsExactly("smithy.api#httpApiKeyAuth")
    }

    @Test
    fun `optional auth marks the requirement optional`() {
        val m = model("""
            ${"$"}version: "2.0"
            namespace example
            @httpBearerAuth
            @auth([httpBearerAuth])
            service Svc { operations: [Op] }
            @optionalAuth
            operation Op { input := {}, output := {} }
        """.trimIndent())

        val svc = m.expectShape(ShapeId.from("example#Svc")).asServiceShape().get()
        val op = m.expectShape(ShapeId.from("example#Op")).asOperationShape().get()
        val req = AuthResolver.resolve(m, svc, op)
        assertThat(req?.optional).isTrue()
