package com.juspay.smithy.mock.discovery

import software.amazon.smithy.model.Model
import software.amazon.smithy.model.knowledge.ServiceIndex
import software.amazon.smithy.model.shapes.OperationShape
import software.amazon.smithy.model.shapes.ServiceShape
import software.amazon.smithy.model.traits.OptionalAuthTrait

data class AuthRequirement(val schemes: List<String>, val optional: Boolean)

object AuthResolver {
    fun resolve(model: Model, service: ServiceShape, op: OperationShape): AuthRequirement? {
        val index = ServiceIndex.of(model)
        val schemes = index.getEffectiveAuthSchemes(service, op)
            .map { (id, _) -> id.toString() }
            .toList()
        if (schemes.isEmpty()) return null
        val optional = op.hasTrait(OptionalAuthTrait::class.java)
        return AuthRequirement(schemes, optional)
    }
}

