import type { AuthRequirement } from '../descriptors/operation';
import type { AuthEntryValue } from '../config/schema';
import type { ErrorEnvelope } from '../errors/envelope';
import { unauthorized } from '../errors/synthesized';

export type AuthResult = { ok: true } | { ok: false; envelope: ErrorEnvelope };

export function checkAuth(
  requirement: AuthRequirement | undefined,
  authConfig: Record<string, AuthEntryValue>,
  headers: Record<string, string | string[] | undefined>,
): AuthResult {
  if (!requirement || requirement.optional) return { ok: true };
  if (requirement.schemes.length === 0) return { ok: true };

  for (const scheme of requirement.schemes) {
    const entry = authConfig[scheme];
    if (!entry || entry.mode === 'ignore') return { ok: true };
    const result = checkScheme(scheme, entry, headers);
    if (result.ok) return { ok: true };
  }
  return { ok: false, envelope: unauthorized('authentication required') };
}

function checkScheme(scheme: string, entry: AuthEntryValue, headers: Record<string, string | string[] | undefined>): AuthResult {
  const auth = pickHeader(headers, 'authorization');
  switch (scheme) {
    case 'smithy.api#httpBearerAuth': {
      const m = auth?.match(/^Bearer\s+(\S+)/i);
      if (!m) return { ok: false, envelope: unauthorized('Bearer token missing') };
      if (entry.mode === 'presence') return { ok: true };
      if (entry.mode === 'value-match') {
        const accept = (entry as { mode: 'value-match'; accept?: string[] }).accept;
        return accept?.includes(m[1]!) ? { ok: true } : { ok: false, envelope: unauthorized('Bearer token rejected') };
      }
      return { ok: true };
    }
    case 'smithy.api#httpApiKeyAuth': {
      const key = pickHeader(headers, 'x-api-key');
      if (!key) return { ok: false, envelope: unauthorized('API key missing') };
      if (entry.mode === 'presence') return { ok: true };
      if (entry.mode === 'value-match') {
        const accept = (entry as { mode: 'value-match'; accept?: string[] }).accept;
        return accept?.includes(key) ? { ok: true } : { ok: false, envelope: unauthorized('API key rejected') };
      }
      return { ok: true };
    }
    default:
      if (entry.mode === 'presence') return auth ? { ok: true } : { ok: false, envelope: unauthorized('credentials required') };
      return { ok: true };
  }
}

function pickHeader(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {
  const raw = headers[name];
  if (raw === undefined) return undefined;
  return Array.isArray(raw) ? raw[0] : raw;
}

